fn split_line<'a>(line: &'a str, delim: &DelimKind) -> Vec<String> {
    match delim {
        DelimKind::Literal(lit) => {
            if lit.is_empty() {
                // split on empty string: Rust's split("") gives ["", "a", "b", ...]? Actually "abc".split("") gives ["", "a", "b", "c", ""].
