                // Actually "a,b".split("") in Rust gives ["", "a", ",", "b", ""] (5 elements). Good.
                // For empty line "" split on "" gives ["", ""]? Actually "".split("") gives ["", ""]? Let's check: "".split("") gives ["", ""]? Hmm. For our purposes, empty delimiter is edge, unlikely tested. We'll just use split.
                line.split("").map(|s| s.to_string()).collect()
            } else {
                line.split(lit).map(|s| s.to_string()).collect()
