}

fn is_gzip_internal_ext(ext: &str) -> bool {
    ext == "gz"
}

fn is_recognized_ext(ext: &str) -> bool {
    matches!(ext, "gz" | "tgz" | "bz2" | "tbz2" | "xz" | "txz" | "lzma" | "Z")
}

fn decompress_gzip(data: &[u8]) -> Result<Vec<u8>, String> {
    use std::io::Read;
    let mut decoder = flate2::read::GzDecoder::new(data);
    let mut out = Vec::new();
    match decoder.read_to_end(&mut out) {
        Ok(_) => Ok(out),
        Err(e) => Err(e.to_string()),
    }
}

fn decompress_external(path: &str, ext: &str) -> Result<Vec<u8>, String> {
    // Determine binary and args
    let (bin, args): (&str, Vec<&str>) = match ext {
        "tgz" | "Z" => ("gzip", vec!["-dc", path]),
        "gz" => ("gzip", vec!["-dc", path]), // though .gz uses internal, this is for fallback? Actually .gz uses internal, not here.
