        "xz" | "txz" | "lzma" => ("xz", vec!["-dc", path]),
        _ => return Err("unsupported".to_string()),
    };
    let output = std::process::Command::new(bin).args(&args).output();
    match output {
        Ok(o) => {
            if o.status.success() {
                Ok(o.stdout)
            } else {
