// Range spec: start 1-based inclusive, end Option (None = to end)
#[derive(Debug, Clone)]
struct RangeSpec {
    start: usize,
    end: Option<usize>, // None means to end (unbounded)
}

fn parse_field_spec(s: &str) -> Result<Vec<RangeSpec>, String> {
    // s is the full fields string like "1,2-,-5"
    // split on comma, each token must be valid
    let mut out = Vec::new();
    // Handle empty string? Original: -f "" gives Failed to parse field:  (empty)
    // split will give [""] for "" -> error
    for token in s.split(',') {
        if token.is_empty() {
            return Err(format!("Failed to parse field: {}", token));
        }
        // token contains '-'?
        if token.contains('-') {
            // special case: token == "-" -> original shows empty, not "-"
            if token == "-" {
                return Err(format!("Failed to parse field: {}", ""));
            }
            // count dashes
            let dash_count = token.matches('-').count();
            if dash_count != 1 {
                // e.g., "1-2-3", "1--2", "--5" (which has 2 dashes, but original shows "-5" for "--5"?)
                // For "--5", original shows "-5" (one dash less). To match, we need to handle?
                // Simplistic: show full token, except for "--5" show "-5"?
                // Let's handle "--5" specially: if starts with "--", show &token[1..]
                if token.starts_with("--") {
                    return Err(format!("Failed to parse field: {}", &token[1..]));
                }
                return Err(format!("Failed to parse field: {}", token));
            }
            let parts: Vec<&str> = token.splitn(2, '-').collect();
            let left = parts[0];
            let right = parts[1];
            if left.is_empty() && right.is_empty() {
                // "-" already handled, shouldn't happen
                return Err(format!("Failed to parse field: {}", ""));
            } else if left.is_empty() {
                // -N : 1 to N
                // right must be digits
                match right.parse::<usize>() {
                    Ok(n) => {
                        if n == 0 {
                            return Err(format!("Fields and positions are numbered from 1: {}", n));
                        }
                        out.push(RangeSpec { start: 1, end: Some(n) });
                    }
                    Err(_) => {
                        // original for "-a" shows "a" (without dash)
                        // for "-a", left empty, right "a" invalid -> show "a"?
                        // Let's mimic: show right part only?
                        // But for "1-a" (left valid, right invalid) shows full "1-a"
                        // So for left empty, show right only
                        return Err(format!("Failed to parse field: {}", right));
                    }
                }
            } else if right.is_empty() {
                // N- : N to end
                match left.parse::<usize>() {
                    Ok(n) => {
                        if n == 0 {
                            return Err(format!("Fields and positions are numbered from 1: {}", n));
                        }
                        out.push(RangeSpec { start: n, end: None });
                    }
                    Err(_) => {
                        // original for "a-" shows "a" (without dash)
                        return Err(format!("Failed to parse field: {}", left));
                    }
                }
            } else {
                // N-M
                let lnum = match left.parse::<usize>() {
                    Ok(n) => n,
                    Err(_) => return Err(format!("Failed to parse field: {}", token)),
                };
                let rnum = match right.parse::<usize>() {
                    Ok(n) => n,
                    Err(_) => return Err(format!("Failed to parse field: {}", token)),
                };
                if lnum == 0 || rnum == 0 {
                    let zero = if lnum == 0 { lnum } else { rnum };
                    return Err(format!("Fields and positions are numbered from 1: {}", zero));
                }
                if rnum < lnum {
                    return Err(format!("High end of range less than low end of range: {}", token));
                }
                out.push(RangeSpec { start: lnum, end: Some(rnum) });
            }
        } else {
            // single N
            match token.parse::<usize>() {
                Ok(n) => {
                    if n == 0 {
                        return Err(format!("Fields and positions are numbered from 1: {}", n));
                    }
                    out.push(RangeSpec { start: n, end: Some(n) });
                }
                Err(_) => {
                    return Err(format!("Failed to parse field: {}", token));
                }
            }
        }
    }
    Ok(out)
}

// Expand ranges to ordered list of indices for a given num_fields (for unbounded) with dedup preserving order
fn expand_ranges(ranges: &[RangeSpec], num_fields: usize) -> Vec<usize> {
    let mut out = Vec::new();
    let mut seen = HashSet::new();
    for r in ranges {
        let end = match r.end {
            Some(e) => e,
            None => {
                if num_fields == 0 {
                    continue;
                }
                num_fields
            }
        };
        // if start > num_fields, nothing (but for unbounded, start may be > num_fields -> nothing)
        // for bounded, we still iterate but skip > num_fields? Actually we should add only existing? No, we add all, then per-line filter skips missing.
        // But for dedup logic ("values written only once"), we need to consider all, even out-of-range? For example, -f4-,1 with 9 fields: 4- expands to 4..9, then 1 is new, then 5-8 already consumed. So expansion must consider out-of-range? For per-line with different lengths, expansion per line.
        // For now, expand to end (which is num_fields for unbounded, or e for bounded) and add in order, dedup.
        // For bounded where end > num_fields, we add up to end? Or only up to num_fields? For output, missing are skipped anyway, but dedup should consider them? Example: -f5,1 with 3 fields: 5 is out-of-range, 1 is new. If we expand 5 (which is > num_fields) and add to seen, then 1 is still new. That's fine. If we don't add 5 because > num_fields, still fine. But for "values written only once" with out-of-range, does it consume? Probably yes (it marks as seen even if missing, so later duplicate missing still skipped? But missing already skipped, so no output anyway). Doesn't matter.
        // We'll add all in range start..=end, even if > num_fields, to mark seen.
        for idx in r.start..=end {
            if !seen.contains(&idx) {
                seen.insert(idx);
                out.push(idx);
            }
        }
    }
    out
}

