{"command": "python3 <<'PY'
import subprocess, re
def run_orig(args, stdin_bytes=None):
    p = subprocess.run(["./executable"]+args, input=stdin_bytes, capture_output=True)
    return p.stdout, p.stderr, p.returncode
def run_new(args, stdin_bytes=None):
    p = subprocess.run(["./target/debug/hck"]+args, input=stdin_bytes, capture_output=True)
    return p.stdout, p.stderr, p.returncode
def norm_err(s):
    try: s=s.decode()
    except: s=str(s)
    return re.sub(r'\[.*? ERROR hck\]', '[X]', s)
def test(args, stdin):
    o_out, o_err, o_code = run_orig(args, stdin)
    n_out, n_err, n_code = run_new(args, stdin)
    o_err_n=norm_err(o_err); n_err_n=norm_err(n_err)
    ok=(o_out==n_out and o_err_n==n_err_n and o_code==n_code)
    if not ok:
        print(f"FAIL {args} stdin={stdin!r} orig={o_out!r} new={n_out!r}")
        return False
    return True

tests = [
    (["-d,", "-F", "b", "-F", "a"], b"a,b,c\nd,e,f\n"),
    (["-d,", "-f3,1", "-E", "x"], b"a,b,c\nd,e,f\n"),
    (["-d,", "-f1", "-F", "c"], b"a,b,c\nd,e,f\n"),  # mixing single-single should still pass (sorted)
    (["-d,", "-E", "a", "-E", "b"], b"a,b\nc,d\n"),
]
for args, stdin in tests:
    print(f"{args} => {'PASS' if test(args, stdin) else 'FAIL'}")
PY
"}

