import subprocess, re, os, gzip
def ro(a,s=None):
    p=subprocess.run(["./executable"]+a, input=s, capture_output=True)
    return p.stdout,p.stderr,p.returncode
def rn(a,s=None):
    p=subprocess.run(["./target/debug/hck"]+a, input=s, capture_output=True)
    return p.stdout,p.stderr,p.returncode
def ne(s):
    try: s=s.decode()
    except: pass
    return re.sub(r'\[.*? ERROR hck\]','[X]',str(s))
# Test README example
for args, stdin in [
    (["-L","-d"," ", "-f1-3,5", "README.md"], None),
    (["-D","___","-f2,1,3"], b"a b c\nd e f\n"),
    (["-r","-F","^a"], b"a,b\nc,d\n"),
    (["-e3,5"], b"a b c d e f\n"),
]:
    o_out,o_err,o_code=ro(args, stdin)
